    internal static void handleOptionConfigDirTemplateSubstitution(parsedCompilerOptions? compilerOptions, RootedDirectoryPath basePath)
    {
        if (compilerOptions == null) return;
        OrderedMap<string, List<string>?>? paths = null;
        if (compilerOptions.CompilerOptions.Paths != null) foreach (var (key, value) in compilerOptions.CompilerOptions.Paths.Entries())
        {
            var substitution = getSubstitutedStringArrayWithConfigDirTemplate(value, basePath);
            if (substitution != null)
            {
                if (paths == null) compilerOptions.CompilerOptions.Paths = paths = compilerOptions.CompilerOptions.Paths.Clone();
                paths.Set(key, substitution);
            }
        }
        if (compilerOptions.unresolvedPaths != null) foreach (var (key, item) in compilerOptions.unresolvedPaths)
        {
            object? value = CommandLineCompilerOptionsMap.Get(key)!.Kind == CommandLineOptionKind.List ? parsePathTexts(item)?.Select(path => (object?)getSubstitutedPathWithConfigDirTemplate(path, basePath)).ToList() : getSubstitutedPathWithConfigDirTemplate(parsePathText(item), basePath);
            ParseCompilerOptions(key, value, compilerOptions.CompilerOptions);
        }
        compilerOptions.unresolvedPaths?.Clear();
    }

