            result.Set("downlevelIteration", options.DownlevelIteration == Tristate.True);
        }
        if (options.ESModuleInterop == Tristate.True || options.ESModuleInterop == Tristate.False)
        {
            result.Set("esModuleInterop", options.ESModuleInterop == Tristate.True);
        }
        if (options.OutFile != default)
        {
            result.Set("outFile", serializeCompilerOptionPath(options.OutFile.AsPath(), configFilePath, caseSensitivity));
        }
        if (options.Diagnostics == Tristate.True || options.Diagnostics == Tristate.False)
        {
            result.Set("diagnostics", options.Diagnostics == Tristate.True);
        }
        if (options.ExtendedDiagnostics == Tristate.True || options.ExtendedDiagnostics == Tristate.False)
        {
            result.Set("extendedDiagnostics", options.ExtendedDiagnostics == Tristate.True);
        }
        if (options.GenerateCpuProfile != default)
        {
            result.Set("generateCpuProfile", serializeCompilerOptionPath(options.GenerateCpuProfile.AsPath(), configFilePath, caseSensitivity));
        }
        if (options.GenerateTrace != default)
        {
            result.Set("generateTrace", serializeCompilerOptionPath(options.GenerateTrace.AsPath(), configFilePath, caseSensitivity));
        }
        if (options.ExplainFiles == Tristate.True || options.ExplainFiles == Tristate.False)
        {
            result.Set("explainFiles", options.ExplainFiles == Tristate.True);
        }
        return result;
    }

    internal static string serializeCompilerOptionEnum(object? value)
    {
        switch (value)
        {
            case JsxEmit flagJsxEmit:
                switch (flagJsxEmit)
                {
                    case JsxEmit.Preserve: return "preserve";
                    case JsxEmit.ReactNative: return "react-native";
                    case JsxEmit.ReactJSX: return "react-jsx";
                    case JsxEmit.ReactJSXDev: return "react-jsxdev";
                    case JsxEmit.React: return "react";
                }
                break;
            case ModuleKind flagModuleKind:
                switch (flagModuleKind)
                {
                    case ModuleKind.CommonJS: return "commonjs";
                    case ModuleKind.AMD: return "amd";
                    case ModuleKind.System: return "system";
                    case ModuleKind.UMD: return "umd";
                    case ModuleKind.ES2015: return "es6";
                    case ModuleKind.ES2020: return "es2020";
                    case ModuleKind.ES2022: return "es2022";
                    case ModuleKind.ESNext: return "esnext";
                    case ModuleKind.Node16: return "node16";
                    case ModuleKind.Node18: return "node18";
                    case ModuleKind.Node20: return "node20";
                    case ModuleKind.NodeNext: return "nodenext";
                    case ModuleKind.Preserve: return "preserve";
                }
                break;
            case ModuleResolutionKind flagModuleResolutionKind:
                switch (flagModuleResolutionKind)
                {
                    case ModuleResolutionKind.Node16: return "node16";
                    case ModuleResolutionKind.NodeNext: return "nodenext";
                    case ModuleResolutionKind.Bundler: return "bundler";
                    case ModuleResolutionKind.Classic: return "classic";
                    case ModuleResolutionKind.Node10: return "node";
                }
                break;
            case ModuleDetectionKind flagModuleDetectionKind:
                switch (flagModuleDetectionKind)
                {
                    case ModuleDetectionKind.Auto: return "auto";
                    case ModuleDetectionKind.Legacy: return "legacy";
                    case ModuleDetectionKind.Force: return "force";
                }
                break;
            case NewLineKind flagNewLineKind:
                switch (flagNewLineKind)
                {
                    case NewLineKind.CRLF: return "crlf";
                    case NewLineKind.LF: return "lf";
                }
                break;
            case ScriptTarget flagScriptTarget:
                switch (flagScriptTarget)
                {
                    case ScriptTarget.ES5: return "es5";
                    case ScriptTarget.ES2015: return "es6";
                    case ScriptTarget.ES2016: return "es2016";
                    case ScriptTarget.ES2017: return "es2017";
                    case ScriptTarget.ES2018: return "es2018";
                    case ScriptTarget.ES2019: return "es2019";
                    case ScriptTarget.ES2020: return "es2020";
                    case ScriptTarget.ES2021: return "es2021";
                    case ScriptTarget.ES2022: return "es2022";
                    case ScriptTarget.ES2023: return "es2023";
                    case ScriptTarget.ES2024: return "es2024";
                    case ScriptTarget.ES2025: return "es2025";
                    case ScriptTarget.ES2026: return "es2026";
                    case ScriptTarget.ESNext: return "esnext";
                }
                break;
        }
        return "";
    }
}
